import IClientContext from './contracts/IClientContext';
import IAuthentication from './connection/contracts/IAuthentication';
export interface FeatureFlagContext {
    flags?: Map<string, string>;
    fetchPromise?: Promise<void>;
    lastFetched?: Date;
    refCount: number;
    cacheDuration: number;
}
/**
 * Shared feature-flag values per workspace.
 * Acquire/release a context per consumer; each reader uses its caller's auth.
 * Responsibilities:
 *   - dedupe in-flight fetches (thundering-herd protection);
 *   - ref-count so context goes away when the last consumer closes;
 *   - clamp server-provided TTL into a safe band.
 *
 * Workspace ID partitions SPOG traffic; normalized host is the fallback.
 */
export default class FeatureFlagCache {
    private context;
    private authProvider?;
    private static sharedContexts;
    private contexts;
    private readonly userAgent;
    private readonly CACHE_DURATION_MS;
    private readonly MIN_CACHE_DURATION_S;
    private readonly MAX_CACHE_DURATION_S;
    constructor(context: IClientContext, authProvider?: IAuthentication | undefined);
    private cacheKey;
    getOrCreateContext(host: string): FeatureFlagContext;
    releaseContext(host: string): void;
    private getRawValue;
    private getValue;
    getBoolean(host: string, name: string, defaultValue?: boolean): Promise<boolean>;
    getInt32(host: string, name: string, defaultValue?: number): Promise<number | undefined>;
    getInt64(host: string, name: string, defaultValue?: bigint): Promise<bigint | undefined>;
    getDouble(host: string, name: string, defaultValue?: number): Promise<number | undefined>;
    getString(host: string, name: string, defaultValue?: string): Promise<string | undefined>;
    getStringList(host: string, name: string, defaultValue?: string[]): Promise<string[] | undefined>;
    /**
     * Strips the `-oss` suffix the feature-flag API does not accept. The server
     * keys off the SemVer triplet only, so anything appended would 404.
     */
    private getDriverVersion;
    private fetchFeatureFlags;
    /** Retries transient failures using the connection's retry policy. */
    private fetchWithRetry;
    private getAuthHeaders;
}
